float hash12(float2 p) {
    float3 p3 = frac(float3(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, float3(p3.y, p3.z, p3.x) + 33.33);
    return frac((p3.x + p3.y) * p3.z);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = p - i;
    float2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = hash12(i), b = hash12(i + float2(1.0, 0.0));
    float c = hash12(i + float2(0.0, 1.0)), d = hash12(i + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(c, d, u.x), u.y);
}
float fbm(float2 p) {
    float s = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { s += a * vnoise(p); p = p * 2.03 + float2(17.1, 9.7); a *= 0.5; }
    return s;
}
// the flood front's lobes, shared by the simulation and the glaze
float floodDist(float2 d, float t, float R) {
    // distance to the dish's centre, warped so the front is lopsided (it runs in faster
    // from the upper right) and lobed like a viscous sheet; the warp scales with the front
    float ang = atan2(d.y, d.x);
    float2 q = float2(cos(ang), sin(ang));
    float lobes = (fbm(q * 2.1 + float2(0.0, t * 0.22) + 23.0) - 0.5) * 2.0;
    float lop = cos(ang + 0.75);
    return length(d) + min(R, 420.0) * (0.10 * lop + 0.09 * lobes);
}

// state: x = substrate a, y = growth b, z = age (slow average of b)
// u: 0 rosette radius px, 1 flood radius px, 2 back to rest 0..1, 3,4 center px,
//    5 seed level, 6 still until (s), 7 state texel px
float4 rest(float2 pos) {
    return float4(1.0, param(5) * input(0, pos).a, 0.0, 1.0);
}
float4 st(float2 p) {
    float2 lo = float2(0.5, 0.5) * param(7);
    return prev(clamp(p, lo, size() - lo));
}
float4 update(float2 pos, float px) {
    if (step_index() == 0 || time() < param(6)) return rest(pos);
    float2 d = pos - float2(param(3), param(4));
    float ang = atan2(d.y, d.x);
    // the rim wanders: lobes of lichen, not a compass circle
    float wob = 0.07 * (fbm(float2(cos(ang), sin(ang)) * 2.2 + 4.0) - 0.5) * 2.0;
    float r = length(d) / (param(0) * (1.0 + wob));
    // dense branching at the heart, coral fingers mid-way, slow lobes at the rim
    float2 fk = r < 0.45 ? lerp(float2(0.040, 0.0605), float2(0.046, 0.0615), r / 0.45)
                         : lerp(float2(0.046, 0.0615), float2(0.0545, 0.0625), saturate((r - 0.45) / 0.4));
    float feed = fk.x + 0.0016 * (fbm(pos / 230.0 + 11.0) - 0.5);
    float kill = fk.y + 0.0010 * (fbm(pos / 190.0 + 5.0) - 0.5);
    kill = lerp(kill, 0.0715, smoothstep(0.86, 1.04, r));
    // under the flood the carving is gone: the growth dies well behind the glaze's front
    float rf = floodDist(d, time(), param(1));
    float under = smoothstep(param(1) + 150.0, param(1) + 165.0, rf);
    if (param(1) < 60.0) under = max(under, 1.0 - smoothstep(0.05, 0.5, input(0, pos).a));
    kill = lerp(kill, 0.10, under);

    float4 s = st(pos);
    float2 lap = -s.xy
        + 0.2 * (st(pos + float2(px, 0)).xy + st(pos - float2(px, 0)).xy
               + st(pos + float2(0, px)).xy + st(pos - float2(0, px)).xy)
        + 0.05 * (st(pos + float2(px, px)).xy + st(pos - float2(px, px)).xy
                + st(pos + float2(px, -px)).xy + st(pos + float2(-px, px)).xy);
    float a = s.x, b = s.y;
    float react = a * b * b;
    a += lap.x - react + feed * (1.0 - a);
    b += 0.5 * lap.y + react - (kill + feed) * b;
    b *= 1.0 - 0.05 * under;
    b = max(b, param(5) * input(0, pos).a);
    float age = s.z + (b - s.z) * 0.0009;
    float4 o = float4(saturate(a), saturate(b), saturate(age), 1.0);
    return lerp(o, rest(pos), param(2));
}

