// u: 0 state texel px, 1 key azimuth rad, 2 key elevation rad, 3 zoom, 4,5 camera center px,
//    6 carve depth px, 7 overhead softbox offset x, 8 exposure, 9,10 dish center px,
//    11..13 glaze absorption rgb, 14 flood radius px, 15 flood on 0..1
static const float RW = 318.0;   // flat well
static const float RC = 398.0;   // top of the wall
static const float RO = 428.0;   // outer edge
static const float HC = 30.0;   // wall height

float4 fieldAt(float2 p) {
    // cubic B-spline over the state grid from four bilinear taps: smooth relief at any zoom
    float tx = param(0);
    float2 u = p / tx - 0.5;
    float2 i = floor(u);
    float2 f = u - i;
    float2 f2 = f * f, f3 = f2 * f;
    float2 w0 = (1.0 - 3.0 * f + 3.0 * f2 - f3) / 6.0;
    float2 w1 = (4.0 - 6.0 * f2 + 3.0 * f3) / 6.0;
    float2 w2 = (1.0 + 3.0 * f + 3.0 * f2 - 3.0 * f3) / 6.0;
    float2 w3 = f3 / 6.0;
    float2 g0 = w0 + w1, g1 = w2 + w3;
    float2 p0 = (i + w1 / g0 - 0.5) * tx, p1 = (i + w3 / g1 + 1.5) * tx;
    return g0.y * (g0.x * input(0, p0) + g1.x * input(0, float2(p1.x, p0.y)))
         + g1.y * (g0.x * input(0, float2(p0.x, p1.y)) + g1.x * input(0, p1));
}
float well(float r) { return 1.0 - smoothstep(RW - 26.0, RW - 6.0, r); }
float carve(float b) { return smoothstep(0.08, 0.27, b); }
float dishH(float r) {
    float bead = 3.0 * exp(-pow((r - (RO - 9.0)) / 7.0, 2.0));
    return HC * smoothstep(RW, RC, r) + bead - (HC + 34.0) * smoothstep(RO - 6.0, RO + 4.0, r);
}
// how far the flood has filled the carving here: 0 open, 1 filled level
float filled(float2 p, float2 dc) {
    // the relief levels just behind the front
    float rf = floodDist(p - dc, time(), param(14));
    return smoothstep(param(14) - 2.0, param(14) + 26.0, rf) * param(15);
}
float faded(float2 p, float2 dc) {
    // the colour of the filled grooves lingers under the gloss, then sinks away
    float rf = floodDist(p - dc, time(), param(14));
    return smoothstep(param(14) + 20.0, param(14) + 150.0, rf) * param(15);
}
float heightAt(float2 p, float2 dc, float depth) {
    float r = length(p - dc);
    return dishH(r) - depth * carve(input(0, p).y) * well(r) * (1.0 - filled(p, dc));
}

float softbox(float3 R, float3 Ls, float2 half_size, float edge, float glow) {
    float3 up = float3(0.0, -1.0, 0.0);
    float3 ux = normalize(cross(up, Ls));
    float3 uy = cross(Ls, ux);
    float d = dot(R, Ls);
    if (d <= 0.0) return 0.0;
    float2 q = float2(dot(R, ux), dot(R, uy)) / d;
    float2 e = abs(q) - half_size;
    float box = 1.0 - smoothstep(-edge, edge, max(e.x, e.y));
    float2 m = max(e, 0.0);
    return box + glow * exp(-dot(m, m) * 40.0);
}

// crazing in the glaze: the edges of a jittered cell pattern
float craze(float2 p) {
    float2 g = p / 74.0;
    float2 i = floor(g);
    float f1 = 9.0, f2 = 9.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            float2 c = i + float2(float(x), float(y));
            float2 o = float2(hash12(c + 3.1), hash12(c + 8.7)) * 0.85 + 0.075;
            float dd = length(c + o - g);
            if (dd < f1) { f2 = f1; f1 = dd; } else if (dd < f2) { f2 = dd; }
        }
    }
    return 1.0 - smoothstep(0.0, 0.012, f2 - f1);
}

float4 shade(float2 pos, float px) {
    float2 sz = size();
    float zoom = param(3);
    float2 p = float2(param(4), param(5)) + (pos - 0.5 * sz) / zoom;
    float dd = 0.8 / zoom;
    float depth = param(6);
    float2 dc = float2(param(9), param(10));
    float2 rel = p - dc;
    float r = length(rel);
    float2 radial = rel / max(r, 1e-3);

    float3 Pw = float3(pos - 0.5 * sz, 0.0);
    float3 V = normalize(float3(0.0, 0.0, 1900.0) - Pw);
    float az = param(1), el = param(2);
    float3 L = float3(cos(el) * cos(az), cos(el) * sin(az), sin(el));
    float2 l2 = normalize(L.xy);
    float tanel = L.z / max(length(L.xy), 1e-3);
    float3 key = float3(1.0, 0.88, 0.74) * 1.95;

    float h0d = dishH(r);
    float dh = (dishH(r + 0.75) - dishH(r - 0.75)) / 1.5;
    float d2h = (dishH(r + 2.0) - 2.0 * h0d + dishH(r - 2.0)) / 4.0;
    float2 lfield = (p - float2(param(4), param(5)));

    if (r > RO + 5.0) {
        // dark honed stone: the dish's shadow on it, a little mineral fleck
        float2 sh = p - (dc - l2 * ((HC + 34.0) / tanel) * 0.9);
        float shade_d = smoothstep(RO - 30.0, RO + 80.0, length(sh));
        float contact = smoothstep(RO + 3.0, RO + 30.0, r);
        float mott = fbm(p / 150.0) * 0.6 + fbm(p / 21.0 + 5.0) * 0.4;
        float fleck = step(0.9975, hash12(floor(p / 1.6) + 4.0)) * 0.6;
        float3 stone = lerp(float3(0.016, 0.0135, 0.012), float3(0.032, 0.026, 0.021), mott) * (1.0 + fleck);
        float fall = 0.45 + 0.85 * saturate(0.5 + 0.5 * dot(normalize(Pw.xy + 1e-3), l2) * length(Pw.xy) / 700.0);
        float3 col = stone * (key * L.z * fall * (0.2 + 0.8 * shade_d) * (0.4 + 0.6 * contact) + 0.07);
        return float4(col * param(8), 1.0);
    }

    // the carved body (filled back in where the flood has passed)
    float fl = filled(p, dc);
    float fc = faded(p, dc);
    float4 s0 = fieldAt(p);
    float wl = well(r) * (1.0 - fl);
    float c0 = carve(s0.y) * wl;
    float cghost = carve(s0.y) * well(r) * (1.0 - fc);
    float gx = (carve(fieldAt(p + float2(dd, 0.0)).y) - carve(fieldAt(p - float2(dd, 0.0)).y)) / (2.0 * dd) * wl;
    float gy = (carve(fieldAt(p + float2(0.0, dd)).y) - carve(fieldAt(p - float2(0.0, dd)).y)) / (2.0 * dd) * wl;
    float2 gbody = -depth * float2(gx, gy) + dh * radial;
    float3 nb = normalize(float3(-gbody, 1.0));

    // the glaze levels over the carving: a gaussian-smoothed copy (value and gradient from one ring)
    float sig = 5.5;
    float gsum = 1.0, cb = c0;
    float2 gg = float2(0.0, 0.0);
    for (int k = 0; k < 12; k++) {
        float a = float(k) * 0.5235988 + 0.26;
        float rad = (k % 2 == 0) ? sig : 2.0 * sig;
        float2 q = float2(cos(a), sin(a)) * rad;
        float w = exp(-0.5 * dot(q, q) / (sig * sig));
        float cv = carve(input(0, p + q).y) * well(length(p + q - dc)) * (1.0 - filled(p + q, dc));
        cb += w * cv;
        gsum += w;
        gg += cv * w * q / (sig * sig);
    }
    cb /= gsum;
    gg /= gsum;
    float follow = 0.42;
    float2 swell = float2(fbm(p / 420.0) - fbm(p / 420.0 + float2(0.6, 0.0)),
                          fbm(p / 420.0 + 7.0) - fbm(p / 420.0 + float2(7.0, 0.6)));
    // orange peel in the gloss: two rotated octaves, so no grid shows at macro
    float2 pr = float2(0.8 * p.x - 0.6 * p.y, 0.6 * p.x + 0.8 * p.y);
    float2 peel = float2(vnoise(pr / 2.9) + 0.5 * vnoise(p / 1.7 + 5.0) - 0.75,
                         vnoise(pr / 2.9 + 9.0) + 0.5 * vnoise(p / 1.7 + 13.0) - 0.75);
    // the flood's leading edge: a meniscus of liquid glaze, and the sheet thickest just behind it
    float rf = floodDist(p - dc, time(), param(14));
    float xm = rf - param(14) - 5.0;
    float menA = param(15) * smoothstep(60.0, 170.0, param(14));
    float men = menA * exp(-xm * xm / 40.0);
    float dmen = menA * (-2.0 * xm / 40.0) * exp(-xm * xm / 40.0) * 5.5;
    float refr = menA * exp(-pow((rf - param(14) + 2.0) / 3.5, 2.0));
    float sheet = param(15) * smoothstep(param(14) - 3.0, param(14) + 6.0, rf) * exp(-max(rf - param(14), 0.0) / 90.0);
    float2 gsurf = -depth * follow * gg + dh * radial + dmen * radial;
    float3 ns = normalize(float3(-gsurf + swell * 0.03 + peel * 0.007 * (1.0 - 0.8 * sheet), 1.0));

    // glaze thickness: thick in the grooves and at the foot of the wall, thin over the rim
    float th = 0.30 + 1.45 * (max(c0, 0.62 * cghost) - follow * cb) * (0.6 + 0.4 * saturate(s0.z * 3.0));
    float inner = 1.0 - smoothstep(RO - 9.0, RO - 5.0, r);
    th += clamp(d2h * 3.2, -0.16, 0.40) * inner;
    th = lerp(0.34, th, inner) + 0.02 * (fbm(p / 9.0) - 0.5);
    th += 0.16 * sheet + 0.05 * men;
    th = max(th, 0.10);
    float3 sigma = float3(param(11), param(12), param(13));
    float3 trans = exp(-2.0 * sigma * th);
    // iron specks under thin glaze, round
    float2 sq = p / 9.0;
    float2 si = floor(sq);
    float sdist = length(sq - si - (0.25 + 0.5 * float2(hash12(si + 31.0), hash12(si + 47.0))));
    float speck = step(0.93, hash12(si + 19.0)) * (1.0 - smoothstep(0.035, 0.075, sdist))
                * (1.0 - smoothstep(0.3, 0.8, th)) * 0.85;
    float3 clay = lerp(float3(0.62, 0.44, 0.30), float3(0.86, 0.83, 0.77), smoothstep(0.10, 0.22, th));
    float3 body = lerp(clay, float3(0.28, 0.17, 0.10), speck);
    float3 albedo = body * trans;

    // raking key light, with the shadows the carving and the rim cast
    float hc = heightAt(p, dc, depth);
    float shadow = 0.0;
    for (int k = 1; k <= 10; k++) {
        float dist = (k <= 5) ? 2.0 * float(k) : 10.0 + 14.0 * float(k - 5);
        float hs = heightAt(p + l2 * dist, dc, depth);
        shadow = max(shadow, saturate(((hs - hc) - dist * tanel) / (2.0 + 0.12 * dist)));
    }
    float wrap = 0.25;
    float ndl = saturate((dot(nb, L) + wrap) / (1.0 + wrap));
    float fall = 0.82 + 0.36 * clamp(dot(normalize(Pw.xy + 1e-3), l2) * length(Pw.xy) / 600.0, -1.0, 1.0);
    float3 amb = float3(0.15, 0.19, 0.25) * (0.7 + 0.3 * nb.z);
    float3 col = albedo * (key * fall * ndl * (1.0 - 0.78 * shadow) + amb);
    col += float3(0.016, 0.046, 0.042) * saturate(th - 0.4) * fall * (1.0 - 0.5 * shadow);

    // bubbles held in the thick glaze, catching the key
    float2 bq = p / 7.0;
    float2 bi = floor(bq);
    float2 bcen = 0.25 + 0.5 * float2(hash12(bi + 71.0), hash12(bi + 13.0));
    float brad = 0.06 + 0.16 * hash12(bi + 37.0);
    float bdist = length(bq - bi - bcen) / brad;
    float bub = step(0.55, hash12(bi + 5.0)) * smoothstep(0.55, 1.1, th);
    float bodyb = bub * (1.0 - smoothstep(0.75, 1.0, bdist));
    float glint = bub * (1.0 - smoothstep(0.0, 0.45, length(bq - bi - bcen + l2 * brad * 0.45) / brad));
    col = col * (1.0 + 0.10 * bodyb) + key * fall * glint * 0.10 * (1.0 - shadow);
    // crazing, faint, where the glaze is thick enough to craze
    col *= 1.0 - 0.10 * craze(p) * smoothstep(0.25, 0.6, th) * inner;

    // the gloss: a long softbox on the key side and a broad one overhead
    float3 R = reflect(-V, ns);
    float ndv = saturate(dot(ns, V));
    float fres = 0.04 + 0.96 * pow(1.0 - ndv, 5.0);
    float3 Lk = normalize(float3(L.xy * 0.95, L.z + 0.2));
    float3 Lo = normalize(float3(param(7), -0.16, 1.0));
    float envk = softbox(R, Lk, float2(0.55, 0.13), 0.03, 0.2) * 15.0;
    float envo = softbox(R, Lo, float2(0.075, 0.05), 0.05, 0.05) * 16.0;
    float env = envk + envo + 0.22 * saturate(R.z);
    col += env * fres * float3(1.0, 0.96, 0.90) * (1.0 - 0.45 * shadow);
    col *= 1.0 - 0.22 * refr;
    return float4(col * param(8), 1.0);
}

float4 shade(float2 pos, float px) {
  float2 p = floor(pos) + floor(time() * 24.0) * float2(37.0, 17.0);
  float h = frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
  float g = frac(sin(dot(p + 3.1, float2(39.346, 11.135))) * 24634.6345);
  float n = (h + g) * 0.5;
  return float4(float3(n), 1.0);
}
